def _matches(line, pattern, flags):
    if "-x" in flags:
        if "-i" in flags:
            matched = line.lower() == pattern.lower()
        else:
            matched = line == pattern
    else:
        if "-i" in flags:
            matched = pattern.lower() in line.lower()
        else:
            matched = pattern in line
    return not matched if "-v" in flags else matched


def grep(pattern, flags, files):
    output = []
    single_file = len(files) == 1
    for fname in files:
        with open(fname) as f:
            lines = f.read().splitlines()
        if "-l" in flags:
            if any(_matches(line, pattern, flags) for line in lines):
                output.append(fname)
            continue
        for lineno, line in enumerate(lines, 1):
            if _matches(line, pattern, flags):
                prefix = ""
                if not single_file:
                    prefix += fname + ":"
                if "-n" in flags:
                    prefix += str(lineno) + ":"
                output.append(prefix + line)
    return "\n".join(output) + ("\n" if output else "")
